export async function getQuota(apiKey: string, apiHost: string) {
  try {
    const quotaUrl = `${apiHost}/api/v1/quota`;
    const response = await fetch(quotaUrl, {
      headers: {
        "X-API-KEY": apiKey,
      },
    });

    const data = await response.json();
    if (!data || !data.success) {
      throw new Error("The API Key is invalid");
    }

    return data.result;
  } catch (error) {
    console.error("Error retrieving quota:", error);
    throw new Error("The API Key is invalid");
  }
}
