import React, { useContext, useState } from "react";
import { Link } from "react-router-dom";
import { DebugContext, LayoutContext } from "../../context";

const SideMenu = () => {
  const { isDebug, setDebug } = useContext(DebugContext);
  const { showMenu, setShowMenu } = useContext(LayoutContext);
  const [clickedTimes, setClickedTimes] = useState(0);
  const onDebugToggle = () => {
    if (isDebug) {
      setDebug(!isDebug);
      setShowMenu(false);
      setClickedTimes(0);
    } else if (clickedTimes >= 10) {
      setDebug(true);
      setShowMenu(false);
      setClickedTimes(0);
    } else {
      setClickedTimes(clickedTimes + 1);
    }
  };
  return (
    <>
      {/* Side Menu */}
      {showMenu && (
        <div
          className="fixed top-0 left-0 w-full h-full bg-dark opacity-40 z-10"
          onClick={() => setShowMenu(false)}
        ></div>
      )}
      <div
        className={`py-2 fixed top-0 left-0 h-full w-[260px] bg-dark transform transition-transform z-20 duration-300 ease-in-out ${
          showMenu ? "translate-x-0" : "-translate-x-full"
        }`}
      >
        <div className="pt-[48px]">
          <div className="p-8 py-6 text-white">
            <nav className="flex flex-col gap-4">
              <Link to="/" onClick={() => setShowMenu(false)} className="hover:text-darkGrey">
                Home
              </Link>
              <Link to="/manual-settings" onClick={() => setShowMenu(false)} className="hover:text-darkGrey">
                Manual Settings
              </Link>
            </nav>
          </div>
          <div className="w-full h-[1px] bg-white/20"></div>
          <div className="p-8 py-6 text-white">
            <nav className="flex flex-col gap-4">
              <a
                href="https://www.arborchat.ai/pro"
                target="_blank"
                rel="noopener noreferrer"
                className="hover:text-darkGrey"
              >
                Pricing
              </a>
              <Link to="/api-key" onClick={() => setShowMenu(false)} className="hover:text-darkGrey">
                Manage API Key
              </Link>
            </nav>
          </div>
          <div className="w-full h-[1px] bg-white/20"></div>

          <div className="p-8 py-6 text-white">
            <nav className="flex flex-col gap-4">
              <a
                href="https://www.arborchat.ai/about-us"
                target="_blank"
                rel="noopener noreferrer"
                className="hover:text-darkGrey"
              >
                Why Arbor
              </a>
              <a
                href="https://www.arborchat.ai/"
                target="_blank"
                rel="noopener noreferrer"
                className="hover:text-darkGrey"
              >
                Get Started
              </a>
              <a
                href="https://t.me/+2SQuvUeWdnNiNDM9"
                target="_blank"
                rel="noopener noreferrer"
                className="hover:text-darkGrey"
              >
                Join Community
              </a>
              <div
                className={`text-sm text-left cursor-default ${!isDebug ? "opacity-0" : ""}`}
                onClick={onDebugToggle}
              >
                {isDebug ? "Disable Debug" : "Enable Debug"}
              </div>
              {isDebug && (
                <div className="text-sm text-left">
                  <span className="text-green">v1.0.0.1</span>
                </div>
              )}
            </nav>
          </div>
        </div>
      </div>
    </>
  );
};
export default SideMenu;
