/* global document, Node, MouseEvent */
import React, { useCallback, useContext, useMemo, useRef, useState, useSyncExternalStore } from "react";
import store from "../../../stores/store";
import { DebugContext } from "../../context";
import NumberStats from "./NumberStats";
import { useActiveCellAddress } from "../../hooks/useActiveCellAddress";
import { IconPlayerPauseFilled, IconRefresh } from "@tabler/icons-react";
import classNames from "classnames";
import { useCellRegeneration } from "../../hooks/useCellRegeneration";

const FormulaInUsed = ({ onValueClick }: { onValueClick: (_value: string) => void }) => {
  const value = useSyncExternalStore(store.subscribe, store.getState);
  const [isRegenerateHover, setIsRegenerateHover] = useState(false);
  const [isDropdownHover, setIsDropdownHover] = useState(false);
  const { isDebug } = useContext(DebugContext);
  const { cellAddresses } = useActiveCellAddress();
  const { onRegenerate, onAbort } = useCellRegeneration();
  const dropdownRef = useRef(null);

  const onValueClickHandler = useCallback(
    (value: string) => {
      onValueClick && onValueClick(value);
    },
    [onValueClick]
  );

  const isLoading = useMemo(() => {
    return !!(value.pendingResolvers.length || value.concurrentCount);
  }, [value.pendingResolvers, value.concurrentCount]);

  const onClickRegenerateEntireActiveCells = useCallback(() => {
    onRegenerate(cellAddresses.formula);
  }, [cellAddresses.formula]);

  const onClickRegenerateEntireErrorCells = useCallback(() => {
    onRegenerate(cellAddresses.error);
  }, [cellAddresses.error]);

  const isDropdownOpen = useMemo(() => {
    return (isRegenerateHover || isDropdownHover) && !isLoading;
  }, [isRegenerateHover, isDropdownHover, isLoading]);

  const haveCellList = useMemo(() => {
    return cellAddresses.formula.length || cellAddresses.error.length;
  }, [cellAddresses.formula, cellAddresses.error]);

  return (
    <div className="p-3">
      <div className="bg-lightGrey flex flex-col gap-1 rounded p-2 px-4">
        <div className="flex flex-row gap-1 justify-between items-center">
          <div className="flex flex-row gap-3">
            <NumberStats
              cellList={cellAddresses.formula}
              label="Active"
              color="green"
              isDisabled={!cellAddresses.formula.length}
              onValueClick={onValueClickHandler}
            />
            <div className="inline-block my-2 h-[20px] min-h-[1em] w-[1px] bg-grey mx-1"></div>
            <NumberStats
              cellList={cellAddresses.error}
              label="Error"
              color="red"
              isDisabled={!cellAddresses.error.length}
              onValueClick={onValueClickHandler}
            />
          </div>
        </div>
        <div className="w-full">
          <div className="duration-200 rounded font-title text-sm transition-colors w-full flex flex-row gap-2">
            <div
              className="relative pb-2 flex-1"
              onMouseEnter={() => setIsRegenerateHover(true)}
              onMouseLeave={() => setIsRegenerateHover(false)}
            >
              <button
                disabled={isLoading || !haveCellList}
                className="w-full rounded-lg bg-darker px-6 py-3 text-white flex flex-row gap-2 w-full text-center justify-center items-center hover:shadow-button disabled:bg-grey disabled:text-darkGrey"
              >
                <span>{isLoading ? "Generating" : "Regenerate"}</span>
                {isLoading ? <IconRefresh size={16} className="animate-spin" /> : null}
              </button>
              <div
                ref={dropdownRef}
                onMouseEnter={() => setIsDropdownHover(true)}
                onMouseLeave={() => setIsDropdownHover(false)}
                className={classNames(
                  "absolute top-full left-0 w-full flex flex-col gap-2 shadow-button bg-white rounded-lg p-2 z-10",
                  isDropdownOpen && haveCellList ? "flex" : "hidden"
                )}
              >
                {cellAddresses.formula.length ? (
                  <button
                    onClick={onClickRegenerateEntireActiveCells}
                    className="w-full rounded-lg px-6 py-2.5 hover:bg-lightGrey text-left"
                  >
                    <span>Entire active cells</span>
                  </button>
                ) : null}
                {cellAddresses.error.length ? (
                  <button
                    onClick={onClickRegenerateEntireErrorCells}
                    className="w-full rounded-lg px-6 py-2.5 hover:bg-lightGrey text-left"
                  >
                    <span>Entire error cells</span>
                  </button>
                ) : null}
              </div>
            </div>
            <div className="pb-2">
              <button
                onClick={onAbort}
                disabled={!isLoading}
                className="p-3 rounded-lg bg-darker text-white disabled:bg-grey disabled:text-darkGrey"
              >
                <IconPlayerPauseFilled size={16} />
              </button>
            </div>
          </div>
        </div>
      </div>
      {isDebug && (
        <div className="bg-lightGrey p-1 mt-2">
          <div className="flex flex-row gap-1">
            <div className="flex flex-row px-1 flex-1">
              <span className="text-green text-sm mr-1">{value.processed}</span>
              <span className="text-sm">Completed</span>
            </div>
            <div className="inline-block h-[20px] min-h-[1em] w-[1px] bg-grey"></div>
            <div className="flex flex-row px-1 flex-1">
              <span className="text-blue text-sm mr-1">{value.concurrentCount}</span>
              <span className="text-sm">Running</span>
            </div>
            <div className="inline-block h-[20px] min-h-[1em] w-[1px] bg-grey"></div>
            <div className="flex flex-row px-1 flex-1">
              <span className="text-grey text-sm mr-1">{value.pendingResolvers.length}</span>
              <span className="text-sm">Pending</span>
            </div>
          </div>
          <div className="flex flex-row gap-2 mt-1">
            <div className="flex flex-row px-2 flex-1 gap-1">
              <span className="text-sm">Max</span>
              <span className="text-sm">{value.concurrency}</span>
              <span className="text-sm">Concurrency</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default FormulaInUsed;
