import React, { useState } from "react";
import { arborAxiosLimiter } from "../../../http/limiter";
import { toAddress } from "../../utils";

interface AnalysisResponse {
  tableTitle: string;
  xAxisTitle: string;
  yAxisTitle: string;
  data: any[][];
}

const TemplateGenerator: React.FC = () => {
  const [query, setQuery] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<AnalysisResponse | null>(null);
  const [apiKey, setApiKey] = useState("");
  const [apiUrl, setApiUrl] = useState(
    "https://arbor-openai-dev-eastus.openai.azure.com/openai/deployments/gpt4o-mini-deployment/chat/completions?api-version=2024-05-01-preview"
  );

  const [promptA, setPromptA] =
    useState(`You are a helpful assistant that analyzes queries and provides structured responses to generate an Excel table or report.
Given a query, analyze it and return a valid JSON response in the following format, as detail as possible,
void putting unit in value, put the unit in the title of the column:
if you are not sure what to put in the table, just put the "NOT_SURE" in the table:
{
  "steps": [
    {
      "title": "string - Title for this step",
      "description": "string - Description of what this step represents", 
      "excelValues": "string[][] - 2D array of data for this step's table"
    }
  ],
  "final": {
    "title": "string - Title for the final result",
    "description": "string - Description for the final result",
    "excelValues": "string[][] - 2D array containing the final table data"
  }
}

Example response:
{
  "steps": [
    {
      "title": "Raw Data Collection",
      "description": "Initial data gathered from sources",
      "excelValues": [["Column1", "Column2"], ["Data1", "Data2"]]
    },
    {
      "title": "Data Processing", 
      "description": "Cleaned and processed data",
      "excelValues": [["Processed1", "Processed2"], ["Value1", "Value2"]]
    }
  ],
  "final": {
    "title": "Final Analysis",
    "description": "Final analysis of the data",
    "excelValues": [["Result1", "Result2"], ["Final1", "Final2"]]
  }
}
Analyze the query carefully to determine:
1. The key data points that need to be displayed
2. The most appropriate way to organize and visualize the data
3. Clear and descriptive labels for all axes and headers

Ensure the response is properly formatted JSON that can be parsed. Keep the arrays reasonably sized (typically 3-10 items).`);
  const [promptB, setPromptB] = useState(`You are a helpful assistant that generates Excel templates. 
given the analysis result, replace the cell that NOT_SURE with excel formular.
if the cell can be generated by formular, just return the formular or else use arborchat for excel to generate the answer.

arborchat for excel provides factual answer of financial question extra formular provided,
these formular will return data type, to get the exact number format, you must populate the answer by using ".answer" at the end of the formular:

=ARBOR_NUMBER("ticker", "query").answer // return number
=ARBOR_DEEP("ticker", "query", [long answer boolean]).answer // return factual answer referenced with newspaper
=ARBOR_FAST("ticker", "query").answer // return factual answer referenced with newspaper


return the response in json format with following structure, you must only return parsed json format with no other text or comments:
[{
    "title": "string - Title for this step",
    "description": "string - Description of what this step represents", 
    "excelValues": [
        [
            {
                "value": "string - value of the cell",
                "type": "string - type of the cell, can be 'title', 'formular', 'value'",
                "formular": "string - formular of the cell, if the cell can be generated by formular, just return the formular or else use arborchat for excel to generate the answer",
                "address": "string - address of the cell"
            }
        ],
        [
            {
                "value": "string - value of the cell",
                "type": "string - type of the cell, can be 'title', 'formular', 'value'",
                "formular": "string - formular of the cell, if the cell can be generated by formular, just return the formular or else use arborchat for excel to generate the answer",
                "address": "string - address of the cell"
            }
        ]
    ]
}]
                `);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      // Step 1: Analyze the query
      const analysisResponse = await arborAxiosLimiter.post(
        apiUrl,
        {
          messages: [
            {
              role: "system",
              content: promptA,
            },
            {
              role: "user",
              content: `Query: ${query}`,
            },
          ],
          max_tokens: 10000,
          temperature: 0,
          n: 1,
        },
        {
          headers: {
            "api-key": apiKey,
          },
        }
      );

      const res = analysisResponse.data.choices[0].message.content.replace(/```json\n|```/g, "");
      console.log(res);

      try {
        const parsedResponse = JSON.parse(res);
        console.log(parsedResponse);

        const { tableValues, originalStartCell } = await Excel.run(async (context) => {
          let startCell = context.workbook.getActiveCell();
          startCell.load("address");
          await context.sync();
          const originalStartCell = startCell.address;
          let clonedStartCell = startCell.getOffsetRange(
            parsedResponse.steps.reduce((acc, step) => acc + step.excelValues.length + 1, 0) +
              parsedResponse.final.excelValues.length +
              1 +
              3,
            0
          );

          const tableValues = [];

          for (const step of [...parsedResponse.steps, parsedResponse.final]) {
            const values = step.excelValues;
            const height = values.length;
            const width = values[0].length;
            startCell.values = step.title;
            startCell.format.fill.color = "#0b1726";
            startCell.format.font.color = "white";
            startCell.format.wrapText = false;

            clonedStartCell.values = step.description;
            clonedStartCell.format.fill.color = "#0b1726";
            clonedStartCell.format.font.color = "white";
            clonedStartCell.format.wrapText = false;

            const range = startCell.getOffsetRange(1, 0).getResizedRange(height - 1, width - 1);
            const clonedRange = clonedStartCell.getOffsetRange(1, 0).getResizedRange(height - 1, width - 1);
            range.load("address");
            await context.sync();
            range.format.columnWidth =
              Math.max(...values.map((row) => Math.max(...row.map((cell) => cell.length)))) * 5;

            range.format.borders.getItem("EdgeLeft").style = "Continuous";
            range.format.borders.getItem("EdgeRight").style = "Continuous";
            range.format.borders.getItem("EdgeTop").style = "Continuous";
            range.format.borders.getItem("EdgeBottom").style = "Continuous";
            range.format.borders.getItem("InsideHorizontal").style = "Continuous";
            range.format.borders.getItem("InsideVertical").style = "Continuous";

            clonedRange.format.columnWidth =
              Math.max(...values.map((row) => Math.max(...row.map((cell) => cell.length)))) * 5;
            clonedRange.format.borders.getItem("EdgeLeft").style = "Continuous";
            clonedRange.format.borders.getItem("EdgeRight").style = "Continuous";
            clonedRange.format.borders.getItem("EdgeTop").style = "Continuous";
            clonedRange.format.borders.getItem("EdgeBottom").style = "Continuous";
            clonedRange.format.borders.getItem("InsideHorizontal").style = "Continuous";
            clonedRange.format.borders.getItem("InsideVertical").style = "Continuous";

            range.values = values;
            clonedRange.values = values;

            const rangeTitles = range.getResizedRange(0, -width + 1);
            rangeTitles.format.fill.color = "#EEEEEE";

            const clonedRangeTitles = clonedRange.getResizedRange(0, -width + 1);
            clonedRangeTitles.format.fill.color = "#EEEEEE";

            const rangeAttr = range.getResizedRange(-height + 1, 0);
            rangeAttr.format.fill.color = "#EEEEEE";

            const clonedRangeAttr = clonedRange.getResizedRange(-height + 1, 0);
            clonedRangeAttr.format.fill.color = "#EEEEEE";

            const valueWithAddress = values.map((row, rowIndex) =>
              row.map((cell, colIndex) => {
                const address = toAddress(range.address.split("!")[1], colIndex, rowIndex);
                return {
                  value: cell,
                  address: address,
                };
              })
            );
            tableValues.push({
              title: step.title,
              description: step.description,
              excelValues: valueWithAddress,
            });
            startCell = startCell.getOffsetRange(height + 1, 0);
            clonedStartCell = clonedStartCell.getOffsetRange(height + 1, 0);
          }
          return {
            originalStartCell,
            tableValues,
          };
        });

        const arborFormularChatResponse = await arborAxiosLimiter.post(
          apiUrl,
          {
            messages: [
              {
                role: "system",
                content: promptB,
              },
              {
                role: "user",
                content: `Analysis result: ${JSON.stringify(tableValues)}`,
              },
            ],
          },
          {
            headers: {
              "api-key": apiKey,
            },
          }
        );
        console.log(arborFormularChatResponse.data.choices[0].message.content);
        const parsedArborFormularChatResponse = JSON.parse(
          arborFormularChatResponse.data.choices[0].message.content.replace(/```json\n|```/g, "")
        );

        await Excel.run(async (context) => {
          const activeSheet = context.workbook.worksheets.getActiveWorksheet();

          parsedArborFormularChatResponse.forEach((step) => {
            const values = step.excelValues;
            values.forEach((row) => {
              row.forEach((data) => {
                if (data.formular) {
                  const cell = activeSheet.getRange(data.address);
                  cell.formulas = data.formular.startsWith("=") ? data.formular : `=${data.formular}`;
                  cell.format.fill.color = "#FFFFFF";
                  cell.calculate();
                }
              });
            });
          });
          await context.sync();
        });
      } catch (error) {
        console.error("Error parsing response or writing to Excel:", error);
        throw error;
      }
    } catch (error) {
      console.error("Error generating template:", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-4">
      <h3 className="text-lg font-semibold mb-4">Template Generator</h3>
      <form onSubmit={handleSubmit}>
        <h4 className="text-lg font-semibold mb-4">API URL</h4>
        <input
          type="text"
          className="w-full p-2 border border-gray-300 rounded-md mb-4"
          value={apiUrl}
          onChange={(e) => setApiUrl(e.target.value)}
          placeholder="Enter API URL"
        />
        <h4 className="text-lg font-semibold mb-4">API Key</h4>
        <input
          type="text"
          className="w-full p-2 border border-gray-300 rounded-md mb-4"
          value={apiKey}
          onChange={(e) => setApiKey(e.target.value)}
          placeholder="Enter your API key"
        />

        <h4 className="text-lg font-semibold mb-4">Prompt A</h4>
        <textarea
          className="w-full p-2 border border-gray-300 rounded-md mb-4"
          rows={4}
          value={promptA}
          onChange={(e) => setPromptA(e.target.value)}
          placeholder="Enter your prompt A"
        />
        <h4 className="text-lg font-semibold mb-4">Prompt B</h4>
        <textarea
          className="w-full p-2 border border-gray-300 rounded-md mb-4"
          rows={4}
          value={promptB}
          onChange={(e) => setPromptB(e.target.value)}
          placeholder="Enter your prompt B"
        />
        <textarea
          className="w-full p-2 border border-gray-300 rounded-md mb-4"
          rows={4}
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Enter your query to generate a template..."
        />
        <button
          type="submit"
          disabled={loading}
          className="w-full rounded-lg bg-darker px-6 py-3 text-white flex flex-row gap-2 w-full text-center justify-center items-center hover:shadow-button disabled:bg-grey disabled:text-darkGrey"
        >
          {loading ? "Generating..." : "Generate Template"}
        </button>
      </form>
    </div>
  );
};

export default TemplateGenerator;
