import React, { useContext, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { DebugContext } from "../../context";
import Instructions from "./Instructions";
import ConsoleView from "../../components/ConsoleView";
import { getFromLocalStorage } from "../../taskpane";
import { VersionWarning } from "./VersionWarning";
import HelperSelection from "./HelperSelection";
import TokenUsage from "./TokenUsage";
import TemplateGenerator from "./TemplateGenerator";

const DashboardPage: React.FC = () => {
  const { isDebug } = useContext(DebugContext);
  const navigate = useNavigate();

  useEffect(() => {
    const localApiKey = getFromLocalStorage("apiKey");
    if (!localApiKey) {
      navigate("/onboarding");
    }
  }, []);

  return (
    <div className="relative">
      <VersionWarning />
      <HelperSelection />
      <div className="w-full h-[1px] bg-lightGrey"></div>
      <TokenUsage />
      <div className="w-full h-[1px] bg-lightGrey"></div>
      <Instructions />
      <TemplateGenerator />
      {isDebug && <ConsoleView />}
    </div>
  );
};

export default DashboardPage;
