/* global Blob, URL, document */

import { create } from "zustand";

export interface ConsoleLog {
  type: "log" | "error";
  args: any[];
}
interface ConsoleState {
  logs: ConsoleLog[];
  addLog: (_log: ConsoleLog) => void;
  clear: () => void;
  saveToFile: () => void;
}

const useConsoleStore = create<ConsoleState>((set) => ({
  logs: [],
  addLog: (log: ConsoleLog) => set((state) => ({ logs: [...state.logs, log] })),
  clear: () => set({ logs: [] }),
  saveToFile: () => {
    const logs = useConsoleStore.getState().logs;
    const content = logs
      .map((log) => {
        return log.args.map((arg) => (typeof arg === "object" ? JSON.stringify(arg) : arg)).join(" ");
      })
      .join("\n");
    const blob = new Blob([content], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `console-logs-${new Date().toISOString()}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  },
}));

// Override console.log to store logs
const originalConsoleLog = console.log;
console.log = (...args) => {
  originalConsoleLog.apply(console, args);
  useConsoleStore.getState().addLog({
    type: "log",
    args,
  });
};

const originalConsoleError = console.error;
console.error = (...args) => {
  originalConsoleError.apply(console, args);
  useConsoleStore.getState().addLog({
    type: "error",
    args: args,
  });
};

export default useConsoleStore;
