/* global window, document */
import { useEffect, useState, useSyncExternalStore } from "react";
import { calculateCellInUsed } from "../utils";
import { useDebounceCallback } from "usehooks-ts";
import store from "../../stores/store";

interface CellAddresses {
  error: string[];
  formula: string[];
  all: string[];
}

export const useActiveCellAddress = () => {
  const [cellAddresses, setCellAddresses] = useState<CellAddresses>({ error: [], formula: [], all: [] });
  const [isLoading, setIsLoading] = useState(false);
  const value = useSyncExternalStore(store.subscribe, store.getState);

  const calculateFormulaInUsed = useDebounceCallback(async () => {
    if (!window.Office || !window.Excel) return;
    if (isLoading) return;
    setIsLoading(true);
    const result = await calculateCellInUsed();
    if (result) {
      const { error, formula, all } = result;
      setCellAddresses({ error, formula, all });
    }
    setIsLoading(false);
  }, 1000);

  useEffect(() => {
    calculateFormulaInUsed();
  }, [value]);

  useEffect(() => {
    if (!window.Office || !window.Excel) return;
    Office.onReady((info) => {
      if (info.host === Office.HostType.Excel) {
        calculateFormulaInUsed();
      }
    });
  }, []);

  useEffect(() => {
    if (!window.Office || !window.Excel) return () => {};
    Office.context.document.addHandlerAsync(Office.EventType.DocumentSelectionChanged, () => {
      console.log("Office.EventType.DocumentSelectionChanged");
      calculateFormulaInUsed();
    });

    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const handler = async (_args) => {
      console.log("context.workbook.worksheets.onChanged");
      calculateFormulaInUsed();
    };

    const visibilityChangeHandler = async () => {
      console.log("visibilitychange", document.visibilityState);
      if (document.visibilityState === "visible") {
        calculateFormulaInUsed();
      }
    };

    Excel.run({ delayForCellEdit: true }, async (context) => {
      context.workbook.worksheets.onChanged.add(handler);
      context.workbook.worksheets.onCalculated.add(handler);
      await context.sync();
    }).catch((error) => {
      console.error(error);
    });
    document.addEventListener("visibilitychange", visibilityChangeHandler);
    return () => {
      document.removeEventListener("visibilitychange", visibilityChangeHandler);
      Office.context.document.removeHandlerAsync(Office.EventType.DocumentSelectionChanged);
      Excel.run({ delayForCellEdit: true }, async (context) => {
        context.workbook.worksheets.onChanged.remove(handler);
        context.workbook.worksheets.onCalculated.remove(handler);
        await context.sync();
      }).catch((error) => {
        console.error(error);
      });
    };
  }, []);

  return { cellAddresses, isLoading };
};
