/* global setInterval, clearInterval */
import React, { FC, useEffect, useMemo, useState } from "react";
import { ARBOR_CHAT_API, getFromLocalStorage } from "../../taskpane";
import { Link } from "react-router-dom";
import { getQuota } from "../../api/getQuota";
import { IconAlertCircleFilled, IconArrowRight, IconReload } from "@tabler/icons-react";
import Alert from "../../components/Alert";
import { delay } from "../../utils";

interface TokenUsageData {
  used: number;
  pending: number;
  totalLimit: number;
  start: number;
  end: number;
}

const TokenUsage: FC = () => {
  const [quota, setQuota] = useState<TokenUsageData>({
    used: 0,
    pending: 0,
    totalLimit: 0,
    start: 0,
    end: 0,
  });
  const [closeAlert, setCloseAlert] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [tokenInvalid, setTokenInvalid] = useState(false);
  const [firstLoaded, setFirstLoaded] = useState(false);

  const fetchQuota = async () => {
    try {
      setIsRefreshing(true);
      let apiHost = getFromLocalStorage("apiHost");
      if (!apiHost || !apiHost.startsWith("http")) {
        apiHost = ARBOR_CHAT_API;
      }
      const token = getFromLocalStorage("apiKey");
      const result = await getQuota(token, apiHost);
      setQuota(result);
      setTokenInvalid(false);
      setError(null);
    } catch (err) {
      setError(err.message);
      setTokenInvalid(true);
    } finally {
      await delay(500);
      setIsRefreshing(false);
      setFirstLoaded(true);
    }
  };

  useEffect(() => {
    fetchQuota();
    if (!tokenInvalid) {
      // Refresh quota every 5 minutes
      const interval = setInterval(fetchQuota, 60000 * 5);
      return () => clearInterval(interval);
    }
    return () => {};
  }, [tokenInvalid]);

  const usedPercentage = useMemo(
    () => (quota?.totalLimit ? 100 - ((quota.used + quota.pending) / quota.totalLimit) * 100 : 0),
    [quota?.used, quota?.pending, quota?.totalLimit]
  );
  const plural = useMemo(
    () => (quota?.totalLimit - quota?.used - quota?.pending === 1 ? "" : "s"),
    [quota?.totalLimit, quota?.used, quota?.pending]
  );

  const isExceeded = useMemo(
    () => quota?.used + quota?.pending >= quota?.totalLimit,
    [quota?.used, quota?.pending, quota?.totalLimit]
  );
  // const endDate = quota.end ? new Date(quota.end).toLocaleDateString() : null;

  if (!firstLoaded) return <div className="h-[150px]" />;

  if (error !== null) {
    return (
      <div className="p-3">
        <div className="flex justify-between items-center">
          <div className="text-red text-sm flex flex-row items-center gap-2">
            <IconAlertCircleFilled size={16} className="text-red" />
            <span>{error}</span>
          </div>
          <Link
            to="/api-key"
            className="text-purple cursor-pointer flex flex-row items-center gap-1 hover:text-purple/80"
          >
            <span>Edit API Key</span>
            <IconArrowRight size={16} />
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="px-3 pt-4 pb-2">
      <h2>Token Usage</h2>
      <p className="pt-1">Tokens used for function generation. Reload manually to see the latest usage.</p>
      <div className="flex flex-row justify-between items-center mt-4">
        <div className="text-sm font-title tracking-title">
          {quota.totalLimit - quota.used - quota.pending} token{plural} left
        </div>
        <button
          onClick={fetchQuota}
          disabled={isRefreshing}
          className="bg-lightGrey rounded text-center p-1 hover:bg-lightGrey/80"
        >
          <IconReload size={16} className={`${isRefreshing ? "animate-spin" : ""}`} />
        </button>
      </div>
      <div className="w-full bg-lightGrey rounded-full h-1 my-2">
        <div className="bg-purple h-1 rounded-full" style={{ width: `${Math.min(usedPercentage, 100)}%` }} />
      </div>
      <div className="flex flex-row justify-between items-center py-1">
        <p>
          Usage: {quota.used + quota.pending}/{quota.totalLimit}
        </p>
        <a
          href="https://www.arborchat.ai/pro"
          target="_blank"
          rel="noopener noreferrer"
          className="text-purple cursor-pointer inline-flex flex-row items-center gap-1"
        >
          <span>Buy More</span>
          <IconArrowRight size={16} />
        </a>
      </div>
      {isExceeded && (
        <Alert error="Out of tokens" hide={closeAlert} onClose={() => setCloseAlert(true)}>
          <p>Your ArborGPT balance is empty. Get more tokens for your account at ease.</p>
          <a
            href="https://www.arborchat.ai/pro"
            target="_blank"
            rel="noopener noreferrer"
            className="cursor-pointer inline-flex flex-row pt-2 items-center gap-1"
          >
            <span>Buy More</span>
            <IconArrowRight size={16} />
          </a>
        </Alert>
      )}
    </div>
  );
};

export default TokenUsage;
