import React, { useContext } from "react";
import { LayoutContext } from "../../context";
import { IconMenu, IconX } from "@tabler/icons-react";

const Header = () => {
  const { showMenu, isLoading, setShowMenu } = useContext(LayoutContext);

  return (
    <>
      <header className="fixed flex justify-center items-center p-3 bg-dark z-50 h-[48px] top-0 left-0 right-0 w-full">
        <a className="flex items-center" href="https://www.arborchat.ai" target="_blank" rel="noopener noreferrer">
          <img src="/assets/logo-white.png" alt="logo" width={73} height={24} />
        </a>
        <div className="flex justify-start absolute left-3">
          <button className="text-white flex items-center hover:text-white/80" onClick={() => setShowMenu(!showMenu)}>
            {showMenu ? <IconX size={24} /> : <IconMenu size={24} />}
          </button>
        </div>
        {isLoading && (
          <div className="absolute bottom-0 h-[2px] left-0 right-0 w-full bg-lightGrey">
            <div className="h-[2px] w-full animate-progress bg-orange origin-left-right"></div>
          </div>
        )}
      </header>
      <div className="h-[48px]"></div>
    </>
  );
};
export default Header;
